    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    if planet1 not in planets or planet2 not in planets:
        return ()
    index1 = planets.index(planet1)
    index2 = planets.index(planet2)
    if index1 < index2:
        return tuple(planets[index1+1:index2])
    else:
        return tuple(planets[index2+1:index1])

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5
    """
    if n < 2:
        return y
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return y
    return x

def cycpattern_check(a, b):
    """You are given 2 words. You need to return True if the second word or any of its rotations is a substring in the first word"""
    # Check if b is a substring of a
    if b in a:
        return True

    # Generate all rotations of b
    rotations = []
    for i in range(len(b)):
        rotations.append(b[i:] + b[:i])

    # Check if any rotation is a substring of a
    for rot in rotations:
        if rot in a:
            return True

    return False

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

    Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    digits = list(map(int, str(abs(num))))
    even = 0
    odd = 0
    for d in digits:
        if d % 2 == 0:
            even += 1
        else:
            odd += 1
    return (even, odd)

def find_max(words):
    if not words:
        return ""
    max_chars = 0
    max_word = words[0]
    for word in words:
        unique_chars = len(set(word))
        if unique_chars > max_chars or (unique_chars == max_chars and word < max_word):
            max_chars = unique_chars
            max_word = word
    return max_word

def eat(number, need, remaining):
    total = number + need
    if total <= remaining:
        return [total, remaining - total]
    else:
        return [remaining, 0]

def do_algebra(operator, operand):
    result = operand[0]
    for i in range(len(operator)):
        op = operator[i]
        num = operand[i + 1]
        if op == '+':
            result += num
        elif op == '-':
            result -= num
        elif op == '*':
            result *= num
        elif op == '//':
            result //= num
        elif op == '**':
            result **= num
        else:
            raise ValueError("Invalid operator")
    return result

def solve(s):
    result = []
    for char in s:
        if char.isalpha():
            result.append(char.swapcase())
        else:
            result.append(char)
    return ''.join(result)

def string_to_md5(text):
    import hashlib
    if not text:
        return None
    return hashlib.md5(text.encode()).hexdigest()

def generate_integers(a, b):
    result = []
    for num in range(a, b + 1):
        for digit in str(num):
            if int(digit) % 2 == 0:
                result.append(int(digit))
    return result
